import importlib

# The function from diffsettings.py
def module_to_dict(module, omittable=lambda k: k.startswith('_')):
    return {k: repr(v) for k, v in module.__dict__.items() if not omittable(k)}

def handle_diffsettings(user_settings_mod, global_settings_mod, options):
    # Mocking the logic in handle()
    # In real code, user_settings_mod would be settings._wrapped
    user_settings = module_to_dict(user_settings_mod)

    if options['default']:
        # Simulate importlib.import_module(options['default'])
        if options['default'] == 'settings.base':
            # Create a mock module for settings.base
            base_settings_dict = {'DEBUG': 'True', 'DATABASE': 'sqlite3', 'SECRET_KEY': 'xyz'}
            base_settings_mod = MagicMock(spec=ModuleType)
            base_settings_mod.__dict__ = base_settings_dict
            default_settings = module_to_dict(base_settings_mod)
        else:
            # Using .format() for Python 3.5 compatibility
            raise ImportError("No module named {}".format(options['default']))
    else:
        default_settings = module_to_dict(global_settings_mod)

    output = []
