def prepend_script_name(url, context):
    """Prepends SCRIPT_NAME to a URL if it is not already absolute."""
    if not url:
        return url

    # Check if URL is absolute (starts with http://, https://, etc.)
    if '://' in url:
        return url

    request = getattr(context, 'request', None)
    if request:
        script_name = request.META.get('SCRIPT_NAME', '')
        if script_name and not url.startswith(script_name):
            # Ensure there's a slash between script_name and url if needed
            # and that the resulting path is not double-slashed if url already starts with '/'
            if not script_name.endswith('/') and not url.startswith('/'):
