            j = int(name[5:])
            if j < 1:
                raise AttributeError(f"'{self.__class__.__name__}' object has no attribute '{name}'")
            if j <= len(self._naxis):
                return self._naxis[j-1]
            else:
                # In FITS, NAXISj for j > NAXIS is 0.
