    def __setattr__(self, name, value):
        if name.startswith('naxis') and name[5:].isdigit():
            j = int(name[5:])
            if j < 1:
                super().__setattr__(name, value)
                return

            if j <= len(self._naxis):
                self._naxis[j-1] = value
                return
            else:
                # Expand self._naxis if it doesn't exist yet
                while len(self._naxis) < j:
                    self._naxis.append(0)
                self._naxis[j-1] = value
                return
        super().__setattr__(name, value)<|"|>,file_path:<|"|>astropy/wcs/wcs.py<|"|>}

